      + `<rect x="190" y="150" width="108" height="14" rx="3" fill="#78909C"/><rect x="194" y="152" width="100" height="9" rx="2" fill="#4FC3F7"/>` + G('an-flash', `<ellipse cx="226" cy="156" rx="12" ry="2" fill="#fff" opacity=".7"/>`)
      + W(244, 162, { anim: 'an-bob' })
