  // 2 · Presentación de la empresa y Ley 16.744
  const escudo = (cx, cy, q) => `<path d="M${cx},${cy - 50} L${cx + 40},${cy - 36} V${cy} Q${cx + 40},${cy + 32} ${cx},${cy + 50} Q${cx - 40},${cy + 32} ${cx - 40},${cy} V${cy - 36}Z" fill="#1565C0" stroke="#0D47A1" stroke-width="3"/>`
