    const blanco = e === 'inversiones' ? `<path d="M244,162 l4,-28 h28 l4,28z" fill="#90A4AE" stroke="#546E7A"/>` + fuego(262, 138, .8) : cajas(232, 164) + fuego(266, 118, .9);
