      g += W(100, 178, { pose: 'point' }) + papel(118, 104, 34, 40, '', '#1565C0') + W(180, 178, { flip: true }) + mesa(222, 178, 90, 44, '#CFD8DC') + queso(234, 134) + queso(262, 134);
