  const angry = (x, y, w = 70) => `<rect x="${x}" y="${y}" width="${w}" height="26" rx="12" fill="#FFEBEE" stroke="#C62828" stroke-width="2"/><path d="M${x + w - 18},${y + 26} l6,9 l2,-9" fill="#FFEBEE" stroke="#C62828" stroke-width="2"/>${txt(x + w / 2, y + 18, '#@%!', 14, '#C62828')}`;
