    if (e === 'agricola') g += tree(70, 182, 1) + tree(250, 182, 1) + `<path d="M172,108 L300,90 L300,150 z" fill="#FFF59D" opacity=".45"/>` + W(160, 184, { pose: 'carry' }) + `<circle cx="164" cy="108" r="3" fill="#FFF59D" stroke="#263238"/>`;
