    si_lq_pis_causas: () => Z(tina(10, 176, 120, { whey: true }) + `<path d="M144,154 q6,10 8,24" stroke="${SUERO}" stroke-width="4" fill="none"/>` + charco(150, 184, 30, SUERO) + lbl(70, 30, 'Suero', '#689F38', 60)
      + hose([[300, 196], [280, 170], [244, 160], [226, 150]], '#212121', 6) + nozzle(226, 150, 200) + W(262, 168, { pose: 'carry', flip: true }) + `<path class="si_lq_dr" d="M196,146 q-14,8 -24,30" stroke="#4FC3F7" stroke-width="4" fill="none" stroke-dasharray="5 4"/>` + charco(196, 188, 30) + lbl(250, 30, 'Agua de lavado', '#0288D1', 116)),
    si_lq_pis_botas: () => Z(suela(50, 50, true) + badge(140, 30, false, 14) + txt(72, 168, 'Suela gastada', 12, '#B71C1C') + divider() + suela(206, 50, false) + badge(300, 30, true, 14) + txt(228, 168, 'Antideslizante', 12, '#1B5E20')),
    si_lq_pis_nocorrer: () => Z(W(78, 180, { pose: 'walk' }) + [0, 1, 2].map(i => `<line x1="${36 - i * 4}" y1="${110 + i * 14}" x2="${56 - i * 4}" y2="${110 + i * 14}" stroke="#D7262B" stroke-width="3" stroke-linecap="round"/>`).join('') + charco(118, 184, 26) + badge(140, 30, false, 14)
      + divider() + W(236, 180, { pose: 'walk', s: .95 }) + charco(296, 186, 18) + badge(300, 30, true, 14) + lbl(80, 30, 'Corriendo', '#D7262B', 84) + lbl(232, 60, 'Caminando', '#2E7D32', 86)),
    si_lq_pis_senal: () => Z(canaleta(30, 180, 150) + charco(150, 172, 40) + W(206, 176, { pose: 'carry', flip: true }) + `<line x1="192" y1="128" x2="166" y2="180" stroke="#1565C0" stroke-width="4" stroke-linecap="round"/><rect x="146" y="178" width="40" height="5" rx="2" fill="#212121"/>` + arrow(140, 186, 100, 186, '#0288D1', 3) + pisoMojado(250, 190)),
    si_lq_pis_derrame: () => Z(`<rect x="40" y="148" width="22" height="26" rx="3" fill="#ECEFF1" stroke="#90A4AE"/><path d="M62,170 l14,6" stroke="#90A4AE" stroke-width="2"/>` + charco(110, 182, 44, '#FFFFFF') + W(196, 178, { pose: 'point', flip: true }) + pisoMojado(236, 192) + bubble(150, 28, 'Seco o aviso y señalizo', 160) + txt(98, 152, 'Leche', 12, '#455A64')),
