    si_lq_aire_ropa: () => Z(W(120, 182, Object.assign({ pose: 'bend' }, AIRE)) + airgun(150, 166, 200) + [0, 1, 2].map(i => `<circle class="si_lq_dr" cx="${132 - i * 6}" cy="${150 + i * 8}" r="3" fill="#B0BEC5"/>`).join('') + badge(286, 40, false, 18) + lbl(96, 34, 'Aire en la piel', '#D7262B', 112) + lbl(96, 58, 'Partículas a los ojos', '#D7262B', 148)),
