  const enchufe = (x, y) => `<rect x="${x}" y="${y - 30}" width="26" height="30" rx="3" fill="#ECEFF1" stroke="#90A4AE" stroke-width="1.5"/><circle cx="${x + 9}" cy="${y - 15}" r="2.4" fill="#263238"/><circle cx="${x + 17}" cy="${y - 15}" r="2.4" fill="#263238"/>`;
