    si_lq_ele_manos: () => Z(enchufe(60, 110) + W(110, 180, { pose: 'point', flip: true }) + [0, 1, 2].map(i => drop(82 + i * 6, 130 + i * 8, .3)).join('') + chispa(76, 94, .8) + badge(144, 28, false, 13) + divider() + enchufe(216, 110) + W(270, 180, { pose: 'point', flip: true }) + badge(304, 28, true, 13) + txt(240, 196, 'Manos secas', 12, '#1B5E20')),
    si_lq_ele_agua: () => Z(tablero(30, 140, false, 90) + `<rect x="94" y="96" width="40" height="30" rx="4" fill="#1E88E5" stroke="#0D47A1"/>` + txt(114, 116, 'M', 13, '#fff') + hose([[300, 196], [270, 170], [220, 160], [200, 134]], '#212121', 6) + W(240, 172, { pose: 'carry', flip: true }) + nozzle(200, 134, 200)
      + `<path class="si_lq_dr" d="M172,128 q-30,-10 -60,0" stroke="#4FC3F7" stroke-width="4" fill="none" stroke-dasharray="5 4"/>` + nope(130, 60, 30)),
    si_lq_ele_cable: () => Z(`<path d="M10,170 q60,-20 120,0 t120,0" stroke="#263238" stroke-width="7" fill="none"/><rect x="118" y="160" width="26" height="12" fill="#263238"/><path d="M122,166 h6 M134,166 h6" stroke="#FFC107" stroke-width="3"/><path d="M128,164 l3,-4 l3,4" stroke="#D84315" stroke-width="2" fill="none"/>` + `<circle class="si_lq_bl" cx="131" cy="166" r="18" fill="none" stroke="#D7262B" stroke-width="3"/>`
      + W(220, 178, { pose: 'point', flip: true, face: 'worried' }) + bubble(170, 30, 'No lo uso y aviso', 130)),
    si_lq_ele_autorizado: () => Z(tablero(40, 160, true, 100) + `<g transform="translate(-20,0)">${W(170, 186, { pose: 'point', flip: true, helmet: false, cofia: false, shirt: '#1565C0', pants: '#37474F', gloves: '#FDD835', glasses: true, boots: '#3E2723', apron: false })}</g>` + lbl(150, 30, 'Electricista autorizado', '#1565C0', 170) + W(266, 180, { flip: true, pose: 'stand' })),
    si_lq_ele_electro: () => Z(tablero(250, 150, false, 90) + `<rect x="286" y="96" width="16" height="22" rx="3" fill="#D7262B"/>` + W(214, 180, { pose: 'point' }) + `<rect x="14" y="96" width="48" height="40" rx="4" fill="#1E88E5" stroke="#0D47A1"/><rect x="20" y="136" width="8" height="44" fill="#78909C"/><rect x="48" y="136" width="8" height="44" fill="#78909C"/>` + W(92, 180, { pose: 'point', flip: true, face: 'pain', anim: 'si_lq_sh' }) + chispa(62, 120, 1) + lbl(238, 30, '1° Corta la energía', '#D7262B', 150) + lbl(90, 30, 'No lo toques', '#D7262B', 104)),
