    si_lq_rui_senal: () => Z(`<rect x="84" y="20" width="152" height="118" rx="8" fill="#fff" stroke="#1565C0" stroke-width="3"/>` + oblig(160, 66, 34) + txt(160, 118, 'USO OBLIGATORIO', 11, '#1565C0') + txt(160, 132, 'PROTECTOR AUDITIVO', 11, '#1565C0') + W(60, 186, { pose: 'walk', muffs: 'on' }) + W(266, 186, { pose: 'carry', flip: true, muffs: 'on' })),
    si_lq_rui_tapones: () => Z(panelBox(6, 32, 98, 140, '1') + plug(36, 110, 1.5) + `<path d="M40,124 q15,10 30,0" stroke="#455A64" stroke-width="2" fill="none"/>` + txt(55, 156, 'Enrolla fino', 11)
      + panelBox(111, 32, 98, 140, '2') + ear(160, 130, .9) + arrow(180, 110, 196, 70, '#1565C0', 3) + txt(160, 156, 'Tira la oreja', 11)
      + panelBox(216, 32, 98, 140, '3') + ear(262, 130, .9) + plug(256, 108, .6) + clock(290, 60, 10) + txt(265, 156, 'Sostén y espera', 11)),
