      + ciclo(43, 90, 20) + `<g transform="translate(121,96) rotate(-90)">${mano(0, 0, .8)}</g>` + arrow(156, 70, 140, 84, '#D7262B', 3) + arrow(156, 120, 140, 106, '#D7262B', 3)
