  S.si_pk_calzado = () => SC(boot(30, 150, .9, false) + badge(130, 40, false, 14) + divider() + boot(190, 150, .9, true) + badge(296, 40, true, 14)
    + labelZ(70, 186, 'Suela lisa', '#C62828', 80) + labelZ(232, 186, 'Antideslizante', '#2E7D32', 104));
