  S.si_pk_zunchtrab = () => SC(strapper(40, 182) + palletBoxes(58, 180, 10, { corner: true }) + lock(116, 150, .8) + P(262, 186, { pose: 'stand', flip: true, glasses: true, gloves: '#455A64' }) + bubbleR(150, 60, 'Aviso a mantención', 132));
  S.si_pk_transp = () => SC(jack(150, 186) + palletBoxes(162, 180, 6) + P(150, 186, { pose: 'walk', flip: true, gloves: '#455A64' }) + arrow(110, 196, 50, 196, '#1565C0'));
