  const bloom = (x, y, s = 1) => cherry(x, y, s, { fruit: false }) + `<g>${CHP.concat([[-40, -10], [40, 0], [0, -30], [-14, 14]]).map(([dx, dy], i) => `<circle cx="${x + dx * s}" cy="${y - 110 * s + dy * s}" r="${3.4 * s}" fill="${i % 3 ? '#FFFFFF' : '#F8BBD0'}" stroke="#F48FB1" stroke-width=".6"/><circle cx="${x + dx * s}" cy="${y - 110 * s + dy * s}" r="${1 * s}" fill="#FBC02D"/>`).join('')}</g>`;
