  S.si_ag_tra_bus = () => svx(ext({ gy: 150 }) + road(150, 182) + rowTrees(150, .38) + bus(20, 184, { open: true }) + W(276, 184, { pose: 'walk', flip: true, s: .8 }) + lbl(116, 30, 'Vehículo autorizado', '#2E7D32', 140));
