  const lying = (x, y, o = {}) => `<g transform="rotate(-90 ${x} ${y})">${W(x, y, Object.assign({ face: 'pain' }, o))}</g>`;
  const cone = (x, y, s = 1) => `<path d="M${x - 9 * s},${y} L${x - 3 * s},${y - 24 * s} h${6 * s} L${x + 9 * s},${y} Z" fill="#FF6F00"/><rect x="${x - 6 * s}" y="${y - 14 * s}" width="${12 * s}" height="${4 * s}" fill="#fff"/><rect x="${x - 12 * s}" y="${y - 2 * s}" width="${24 * s}" height="${3 * s}" fill="#E65100"/>`;
  const tape = (x1, x2, y) => `<line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="#FFC20E" stroke-width="4" stroke-dasharray="8 8"/><line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="#D7262B" stroke-width="4" stroke-dasharray="8 8" stroke-dashoffset="8"/>`;
  const lamp = (x, y) => `<rect x="${x - 28}" y="${y}" width="56" height="8" rx="3" fill="#ECEFF1" stroke="#90A4AE"/><line x1="${x - 20}" y1="${y}" x2="${x - 20}" y2="0" stroke="#90A4AE"/><line x1="${x + 20}" y1="${y}" x2="${x + 20}" y2="0" stroke="#90A4AE"/>`;
  S.si_es_a_intro = () => { const [fx, fy] = tStep(170, 165, 96, 2, 4); return V(taller() + lamp(196, 20) + tijera(170, 165, 96) + W(fx, fy, { pose: 'stop' }) + label(70, 60, '¡Cuidado!', '#D7262B', 74) + txt(70, 90, 'Caídas de altura', 13, '#C62828') + txt(70, 106, 'y de escalera', 13, '#C62828')); };
  S.si_es_a_revisar = () => V(taller() + tijera(70, 160, 110, { broken: true, bg: E() === 'agricola' ? '#C9A77C' : '#DDE3EA' }) + label(70, 34, 'Peldaño roto', '#C62828', 90) + badge(130, 40, false, 14) + divider() + tijera(240, 160, 110) + `<circle cx="211" cy="158" r="10" fill="none" stroke="#2E7D32" stroke-width="2.5"/><circle cx="264" cy="158" r="10" fill="none" stroke="#2E7D32" stroke-width="2.5"/><ellipse cx="238" cy="114" rx="22" ry="9" fill="none" stroke="#2E7D32" stroke-width="2.5"/>` + label(222, 34, 'Zapatas y seguro', '#2E7D32', 116) + badge(296, 40, true, 14));
  S.si_es_a_tijera = () => { const [ax, ay] = [70, 165 - 80], [bx2, by2] = tStep(240, 165, 80, 2, 3); return V(taller() + tijera(70, 165, 80, { n: 3 }) + W(ax + 2, ay - 4, { s: .85, face: 'worried' }) + badge(130, 40, false, 14) + divider() + tijera(240, 165, 80, { n: 3 }) + W(bx2, by2, { s: .85, pose: 'stop' }) + badge(296, 40, true, 14)); };
