  const O = o => Object.assign({ emp: 'inversiones' }, o || {});
  const fileCab = (x, y, n, open) => { let g = `<rect x="${x}" y="${y - n * 16 - 2}" width="30" height="${n * 16 + 2}" fill="#90A4AE" stroke="#607D8B"/>`; for (let i = 0; i < n; i++) { const dy = y - (i + 1) * 16; const op = open.indexOf(i) >= 0; g += op ? `<rect x="${x + 30}" y="${dy + 1}" width="26" height="14" fill="#B0BEC5" stroke="#607D8B"/><rect x="${x + 54}" y="${dy + 6}" width="4" height="4" fill="#455A64"/><rect x="${x + 34}" y="${dy - 2}" width="18" height="4" fill="#FFF8E1"/>` : `<rect x="${x + 29}" y="${dy + 6}" width="3" height="4" fill="#455A64"/>`; } return g; };
  const bookcase = (x, y, heavyTop, anchored) => { let g = `<rect x="${x}" y="${y - 96}" width="54" height="96" fill="#A1887F" stroke="#6D4C41"/>` + [24, 48, 72].map(d => `<rect x="${x}" y="${y - d}" width="54" height="3" fill="#6D4C41"/>`).join('');
    const heavy = (bx, by) => `<rect x="${bx}" y="${by - 20}" width="22" height="20" fill="#8D6E3F" stroke="#5D4037"/><rect x="${bx + 24}" y="${by - 20}" width="22" height="20" fill="#8D6E3F" stroke="#5D4037"/>` + txt(bx + 23, by - 6, 'kg', 9, '#fff');
    const light = (bx, by) => [0, 1, 2, 3, 4, 5].map(i => `<rect x="${bx + i * 7.5}" y="${by - 16}" width="6" height="16" fill="${['#1E88E5', '#E53935', '#43A047', '#FDD835', '#8E24AA', '#FB8C00'][i]}"/>`).join('');
    g += heavyTop ? heavy(x + 4, y - 75) + light(x + 4, y - 3) : light(x + 4, y - 75) + heavy(x + 4, y - 3);
    g += light(x + 4, y - 51) + light(x + 4, y - 27);
    if (anchored) g += `<path d="M${x + 54},${y - 92} h10 v-8" stroke="#263238" stroke-width="3" fill="none"/>`;
    return g; };
  const zap = (x, y, n, c) => `<rect x="${x}" y="${y - 10}" width="${14 + n * 13}" height="10" rx="3" fill="${c || '#ECEFF1'}" stroke="#78909C"/>` + [...Array(n)].map((_, i) => `<rect x="${x + 6 + i * 13}" y="${y - 14}" width="8" height="7" rx="2" fill="#37474F"/>`).join('');
  const heater = (x, y, glow) => `<rect x="${x}" y="${y - 32}" width="44" height="28" rx="3" fill="#ECEFF1" stroke="#90A4AE"/>` + [0, 1, 2, 3, 4, 5].map(i => `<rect x="${x + 3 + i * 7}" y="${y - 30}" width="5" height="24" rx="2" fill="#CFD8DC"/>`).join('') + `<circle cx="${x + 6}" cy="${y - 2}" r="3" fill="#455A64"/><circle cx="${x + 38}" cy="${y - 2}" r="3" fill="#455A64"/>` + (glow ? `<g class="si_es_pu">` + [0, 1, 2].map(i => `<path d="M${x + 10 + i * 12},${y - 36} q4,-6 0,-12 q-4,-6 0,-12" stroke="#FF7043" stroke-width="2" fill="none"/>`).join('') + `</g>` : '');
  const curtain = (x, y) => `<path d="M${x},${y} h30 v100 q-8,4 -15,0 q-8,4 -15,0 z" fill="#CE93D8" stroke="#8E24AA"/>`;
  const counter = (x, w) => `<rect x="${x}" y="122" width="${w}" height="6" fill="#ECEFF1" stroke="#90A4AE"/><rect x="${x}" y="128" width="${w}" height="37" fill="#BCAAA4" stroke="#8D6E63"/><line x1="${x + w / 2}" y1="130" x2="${x + w / 2}" y2="163" stroke="#8D6E63"/>`;
  const kettle = (x, y) => `<path d="M${x},${y} h28 l-3,-24 q-11,-6 -22,0 z" fill="#B0BEC5" stroke="#546E7A"/><path d="M${x + 26},${y - 18} q8,0 6,12" stroke="#546E7A" stroke-width="3" fill="none"/><path d="M${x + 2},${y - 18} l-8,-6" stroke="#546E7A" stroke-width="3"/><g class="si_es_up"><path d="M${x + 10},${y - 30} q-3,-6 2,-12 M${x + 18},${y - 30} q-3,-6 2,-12" stroke="#B0BEC5" stroke-width="2" fill="none"/></g>`;
  const stairs = (x0, y0, n, dx, dy) => { let g = `<path d="M${x0},${y0}`; for (let i = 0; i < n; i++) g += ` v${-dy} h${dx}`; g += ` V${y0} Z" fill="#BCAAA4" stroke="#8D6E63"/>`; return g; };
  const exitSign = (x, y) => `<rect x="${x}" y="${y}" width="60" height="22" rx="3" fill="#2E7D32"/>` + txt(x + 30, y + 15, 'SALIDA', 11, '#fff');
  const stool = (x, y) => `<path d="M${x},${y} l4,-22 h28 l4,22" fill="none" stroke="#1565C0" stroke-width="3"/><rect x="${x + 2}" y="${y - 24}" width="32" height="5" fill="#1565C0"/><rect x="${x + 6}" y="${y - 12}" width="24" height="4" fill="#1565C0"/>`;
