  S.si_es_o_archivador = () => V(officeBg() + bookcase(50, 150, true) + `<path d="M48,62 l-6,-6 M52,58 l-2,-8" stroke="#D7262B" stroke-width="2.5"/>` + badge(140, 24, false, 13) + divider() + bookcase(210, 150, false, true) + `<rect x="260" y="40" width="4" height="120" fill="#ECEFF1" opacity="0"/>` + label(237, 186, 'Anclado', '#2E7D32', 64) + badge(300, 24, true, 13));
  S.si_es_o_enchufes = () => V(officeBg() + socket(20, 90) + `<path d="M33,124 q0,30 20,32" stroke="#263238" stroke-width="3" fill="none"/>` + zap(50, 160, 4) + `<path d="M64,146 q10,-20 30,-14" stroke="#263238" stroke-width="3" fill="none"/>` + zap(94, 140, 3) + `<path d="M108,126 q0,-10 10,-14 M121,126 q4,-12 14,-14 M134,126 q6,-10 10,-14" stroke="#263238" stroke-width="2.5" fill="none"/>` + heater(70, 120).replace(/<g class="si_es_pu">[\s\S]*<\/g>/, '') + badge(140, 24, false, 13) + divider() + socket(176, 90) + `<path d="M189,124 q0,30 20,32" stroke="#263238" stroke-width="3" fill="none"/>` + zap(206, 160, 4) + `<rect x="${206 + 14 + 4 * 13 - 10}" y="152" width="7" height="6" fill="#D7262B"/>` + `<path d="M226,146 q10,-30 40,-40" stroke="#263238" stroke-width="2.5" fill="none"/>` + `<rect x="250" y="80" width="40" height="28" rx="3" fill="#263238"/><rect x="254" y="84" width="32" height="20" fill="#64B5F6"/>` + badge(300, 24, true, 13));
  S.si_es_o_calefactor = () => V(officeBg() + win(16, 20, 70, 70) + curtain(60, 16) + heater(70, 160, true) + `<rect x="100" y="108" width="20" height="16" fill="#FFF8E1" stroke="#BCAAA4" transform="rotate(-8 110 116)"/>` + badge(140, 24, false, 13) + divider() + win(176, 20, 70, 70) + curtain(220, 16) + heater(270, 160, true) + `<path d="M250,170 h20 M250,166 v8 M270,166 v8" stroke="#2E7D32" stroke-width="2"/>` + arrow(252, 176, 226, 176, '#2E7D32', 2) + label(250, 194, '1 metro', '#2E7D32', 60) + badge(300, 24, true, 13));
  S.si_es_o_cocina = () => V(officeBg() + counter(10, 140) + `<g transform="rotate(10 140 122)">` + kettle(124, 122) + `</g>` + `<path d="M144,124 q8,20 -4,40" stroke="#263238" stroke-width="2.5" fill="none"/>` + badge(140, 24, false, 13) + divider() + counter(166, 154) + socket(196, 80) + kettle(214, 122) + `<path d="M209,114 q-2,-6 0,-10" stroke="#263238" stroke-width="2.5" fill="none"/>` + `<rect x="262" y="96" width="44" height="26" rx="3" fill="#ECEFF1" stroke="#78909C"/><rect x="266" y="100" width="28" height="18" fill="#263238"/>` + badge(300, 24, true, 13));
  S.si_es_o_escaleras = () => V(officeBg() + stairs(20, 165, 5, 22, 18) + `<line x1="20" y1="122" x2="130" y2="32" stroke="#455A64" stroke-width="3"/>` + W(76, 111, O({ pose: 'carry', flip: true, face: 'worried' })) + `<rect x="58" y="56" width="7" height="11" rx="1.5" fill="#263238"/>` + badge(140, 24, false, 13) + divider() + stairs(176, 165, 5, 22, 18) + `<line x1="176" y1="128" x2="286" y2="38" stroke="#455A64" stroke-width="3"/>` + W(232, 111, O({ flip: true })) + badge(300, 24, true, 13));
